INSERT INTO @t VALUES (N'az', N'A change applies to new deposits only. A customer''s rate is fixed when the deposit is opened. Turning a term off hides it from customers.', N'Dəyişiklik yalnız yeni depozitlərə aiddir. Müştərinin faizi depozit açılanda sabitlənir. Müddəti söndürmək onu müştərilərdən gizlədir.');
INSERT INTO @t VALUES (N'ru', N'A change applies to new deposits only. A customer''s rate is fixed when the deposit is opened. Turning a term off hides it from customers.', N'Изменение действует только для новых вкладов. Ставка клиента фиксируется при открытии вклада. Отключение срока скрывает его от клиентов.');
INSERT INTO @t VALUES (N'az', N'a customer account locked for a few minutes after repeated wrong passwords.', N'təkrarlanan yanlış paroldan sonra müştəri hesabının bir neçə dəqiqəlik bloklanması.');
