INSERT INTO @t VALUES (N'az', N'A design used by a card type or by customer cards cannot be deleted.', N'Kart növü və ya müştəri kartları tərəfindən istifadə olunan dizayn silinə bilməz.');
INSERT INTO @t VALUES (N'ru', N'A design used by a card type or by customer cards cannot be deleted.', N'Дизайн, используемый типом карты или картами клиентов, удалить нельзя.');
INSERT INTO @t VALUES (N'az', N'A new card face. Up to 3 designs can be shown on Home, the smallest order comes first.', N'Yeni kart üzü. Ana səhifədə ən çox 3 dizayn göstərilə bilər, ən kiçik sıra əvvəldə gəlir.');
INSERT INTO @t VALUES (N'ru', N'A new card face. Up to 3 designs can be shown on Home, the smallest order comes first.', N'Новая сторона карты. На главной можно показать до 3 дизайнов, сначала идёт наименьший порядок.');
INSERT INTO @t VALUES (N'az', N'A new column for the About block: a small image, a title and a short text.', N'"Haqqımızda" blokunun yeni sütunu: kiçik şəkil, başlıq və qısa mətn.');
INSERT INTO @t VALUES (N'ru', N'A new column for the About block: a small image, a title and a short text.', N'Новая колонка блока «О нас»: маленькое изображение, заголовок и короткий текст.');
INSERT INTO @t VALUES (N'az', N'A partner logo for the moving strip under the Home headline.', N'Ana səhifə başlığının altındakı hərəkətli zolaq üçün tərəfdaş loqosu.');
INSERT INTO @t VALUES (N'ru', N'A partner logo for the moving strip under the Home headline.', N'Логотип партнёра для бегущей полосы под заголовком главной страницы.');
INSERT INTO @t VALUES (N'az', N'A record of staff decisions and account changes: who did what, to whom and when. Entries can''t be edited or deleted.', N'İşçi qərarlarının və hesab dəyişikliklərinin qeydi: kim, kimə, nə vaxt nə etdi. Qeydlər redaktə və ya silinə bilməz.');
INSERT INTO @t VALUES (N'ru', N'A record of staff decisions and account changes: who did what, to whom and when. Entries can''t be edited or deleted.', N'Журнал решений сотрудников и изменений счетов: кто, кому и когда что сделал. Записи нельзя изменить или удалить.');
INSERT INTO @t VALUES (N'az', N'A restricted customer can''t sign in, send money, pay bills, top up or take a loan until the account is restored. Write why, so the next person knows.', N'Məhdudlaşdırılmış müştəri hesab bərpa olunana qədər daxil ola, pul göndərə, ödəniş edə, balans artıra və ya kredit götürə bilməz. Səbəbi yazın ki, növbəti şəxs bilsin.');
INSERT INTO @t VALUES (N'ru', N'A restricted customer can''t sign in, send money, pay bills, top up or take a loan until the account is restored. Write why, so the next person knows.', N'Ограниченный клиент не может входить, отправлять деньги, оплачивать счета, пополнять баланс и брать кредит, пока счёт не восстановлен. Напишите причину, чтобы следующий сотрудник знал.');
INSERT INTO @t VALUES (N'az', N'A short phrase for the moving line under the Home headline.', N'Ana səhifə başlığının altındakı hərəkətli sətir üçün qısa ifadə.');
