INSERT INTO @t VALUES (N'az', N'Administrators can do everything except give or remove roles. Accountants decide loans and card rules, customer support helps customers, security handles suspicious reports and freezes.', N'Adminlər rol vermək və almaqdan başqa hər şeyi edə bilər. Mühasiblər kredit və kart qaydalarına qərar verir, müştəri dəstəyi müştərilərə kömək edir, təhlükəsizlik şübhəli bildirişlərə və dondurmalara baxır.');
