INSERT INTO @t VALUES (N'az', N'Change the fee, the cashback, the transfer rules or the design. The type itself stays the same, because the app finds its rules by the type.', N'Haqqı, keşbeki, köçürmə qaydalarını və ya dizaynı dəyişin. Növün özü dəyişmir, çünki tətbiq qaydaları növə görə tapır.');
INSERT INTO @t VALUES (N'ru', N'Change the fee, the cashback, the transfer rules or the design. The type itself stays the same, because the app finds its rules by the type.', N'Измените плату, кешбэк, правила переводов или дизайн. Сам тип не меняется, потому что приложение находит правила по типу.');
INSERT INTO @t VALUES (N'az', N'Change the label, title or description of the block.', N'Blokun etiketini, başlığını və ya təsvirini dəyişin.');
INSERT INTO @t VALUES (N'ru', N'Change the label, title or description of the block.', N'Измените метку, заголовок или описание блока.');
INSERT INTO @t VALUES (N'az', N'Change the label, title or description of the block. The video is changed on its own page.', N'Blokun etiketini, başlığını və ya təsvirini dəyişin. Video ayrıca səhifədə dəyişdirilir.');
INSERT INTO @t VALUES (N'ru', N'Change the label, title or description of the block. The video is changed on its own page.', N'Измените метку, заголовок или описание блока. Видео меняется на отдельной странице.');
INSERT INTO @t VALUES (N'az', N'Change the name or the logo. Leave the logo as it is to keep the current one.', N'Adı və ya loqonu dəyişin. Hazırkı loqonu saxlamaq üçün toxunmayın.');
INSERT INTO @t VALUES (N'ru', N'Change the name or the logo. Leave the logo as it is to keep the current one.', N'Измените название или логотип. Оставьте логотип как есть, чтобы сохранить текущий.');
INSERT INTO @t VALUES (N'az', N'Change the name, hide the provider from customers or upload a new logo. Leave the logo as it is to keep the current one.', N'Adı dəyişin, provayderi müştərilərdən gizlədin və ya yeni loqo yükləyin. Hazırkı loqonu saxlamaq üçün toxunmayın.');
INSERT INTO @t VALUES (N'ru', N'Change the name, hide the provider from customers or upload a new logo. Leave the logo as it is to keep the current one.', N'Измените название, скройте поставщика от клиентов или загрузите новый логотип. Оставьте логотип как есть, чтобы сохранить текущий.');
INSERT INTO @t VALUES (N'az', N'Change the phrase that moves across the line on the Home page.', N'Ana səhifədəki hərəkətli sətirdə gedən ifadəni dəyişin.');
INSERT INTO @t VALUES (N'ru', N'Change the phrase that moves across the line on the Home page.', N'Измените фразу, которая бежит по строке на главной странице.');
INSERT INTO @t VALUES (N'az', N'Change the text on the left of the top block of the Home page.', N'Ana səhifənin yuxarı blokunun solundakı mətni dəyişin.');
INSERT INTO @t VALUES (N'ru', N'Change the text on the left of the top block of the Home page.', N'Измените текст слева в верхнем блоке главной страницы.');
INSERT INTO @t VALUES (N'az', N'Change the text or the button of this card.', N'Bu kartın mətnini və ya düyməsini dəyişin.');
INSERT INTO @t VALUES (N'ru', N'Change the text or the button of this card.', N'Измените текст или кнопку этой карточки.');
INSERT INTO @t VALUES (N'az', N'Change the title, the description or the icon. Leave the icon as it is to keep the current one. The number stays the same, because the card opens a fixed part of the app.', N'Başlığı, təsviri və ya ikonu dəyişin. Hazırkı ikonu saxlamaq üçün toxunmayın. Nömrə dəyişmir, çünki kart tətbiqin sabit hissəsini açır.');
INSERT INTO @t VALUES (N'ru', N'Change the title, the description or the icon. Leave the icon as it is to keep the current one. The number stays the same, because the card opens a fixed part of the app.', N'Измените заголовок, описание или иконку. Оставьте иконку как есть, чтобы сохранить текущую. Номер не меняется, потому что карточка открывает фиксированную часть приложения.');
INSERT INTO @t VALUES (N'az', N'Change the title, the order, whether it is shown on Home or the image. Leave the image as it is to keep the current one.', N'Başlığı, sıranı, Ana səhifədə göstərilməsini və ya şəkli dəyişin. Hazırkı şəkli saxlamaq üçün toxunmayın.');
INSERT INTO @t VALUES (N'ru', N'Change the title, the order, whether it is shown on Home or the image. Leave the image as it is to keep the current one.', N'Измените заголовок, порядок, показ на главной или изображение. Оставьте изображение как есть, чтобы сохранить текущее.');
INSERT INTO @t VALUES (N'az', N'Change the title, the text or the image. Leave the image as it is to keep the current one.', N'Başlığı, mətni və ya şəkli dəyişin. Hazırkı şəkli saxlamaq üçün toxunmayın.');
INSERT INTO @t VALUES (N'ru', N'Change the title, the text or the image. Leave the image as it is to keep the current one.', N'Измените заголовок, текст или изображение. Оставьте изображение как есть, чтобы сохранить текущее.');
