INSERT INTO @t VALUES (N'az', N'Click here or drag a new one in. A square PNG with a transparent background looks best. PNG, JPEG or WebP, up to 2 MB.', N'Bura klikləyin və ya yenisini sürükləyin. Şəffaf fonlu kvadrat PNG ən yaxşı görünür. PNG, JPEG və ya WebP, 2 MB-a qədər.');
INSERT INTO @t VALUES (N'ru', N'Click here or drag a new one in. A square PNG with a transparent background looks best. PNG, JPEG or WebP, up to 2 MB.', N'Нажмите здесь или перетащите новый файл. Лучше всего подходит квадратный PNG с прозрачным фоном. PNG, JPEG или WebP, до 2 МБ.');
INSERT INTO @t VALUES (N'az', N'Click here or drag a new one in. A square PNG, JPEG or WebP, up to 2 MB.', N'Bura klikləyin və ya yenisini sürükləyin. Kvadrat PNG, JPEG və ya WebP, 2 MB-a qədər.');
INSERT INTO @t VALUES (N'ru', N'Click here or drag a new one in. A square PNG, JPEG or WebP, up to 2 MB.', N'Нажмите здесь или перетащите новый файл. Квадратный PNG, JPEG или WebP, до 2 МБ.');
INSERT INTO @t VALUES (N'az', N'Click here or drag a new one in. PNG, JPEG or WebP, up to 2 MB.', N'Bura klikləyin və ya yenisini sürükləyin. PNG, JPEG və ya WebP, 2 MB-a qədər.');
INSERT INTO @t VALUES (N'ru', N'Click here or drag a new one in. PNG, JPEG or WebP, up to 2 MB.', N'Нажмите здесь или перетащите новый файл. PNG, JPEG или WebP, до 2 МБ.');
INSERT INTO @t VALUES (N'az', N'Click here or drag it in. MP4 or WebM, up to 50 MB. Uploading can take a moment.', N'Bura klikləyin və ya sürükləyin. MP4 və ya WebM, 50 MB-a qədər. Yükləmə bir az çəkə bilər.');
INSERT INTO @t VALUES (N'ru', N'Click here or drag it in. MP4 or WebM, up to 50 MB. Uploading can take a moment.', N'Нажмите здесь или перетащите файл. MP4 или WebM, до 50 МБ. Загрузка может занять немного времени.');
INSERT INTO @t VALUES (N'az', N'Click here or drag it in. PNG, JPEG or WebP, up to 2 MB.', N'Bura klikləyin və ya sürükləyin. PNG, JPEG və ya WebP, 2 MB-a qədər.');
INSERT INTO @t VALUES (N'ru', N'Click here or drag it in. PNG, JPEG or WebP, up to 2 MB.', N'Нажмите здесь или перетащите файл. PNG, JPEG или WebP, до 2 МБ.');
INSERT INTO @t VALUES (N'az', N'Commissions come from transfers above each card''s free limit; opening fees from Silver, Gold and extra cards; interest and penalties from loan payments made in the month.', N'Komissiyalar hər kartın pulsuz limitini aşan köçürmələrdən; açılış haqları Silver, Gold və əlavə kartlardan; faiz və cərimələr ay ərzindəki kredit ödənişlərindən gəlir.');
INSERT INTO @t VALUES (N'ru', N'Commissions come from transfers above each card''s free limit; opening fees from Silver, Gold and extra cards; interest and penalties from loan payments made in the month.', N'Комиссии поступают с переводов сверх бесплатного лимита карты; плата за открытие — с Silver, Gold и дополнительных карт; проценты и пени — с платежей по кредитам за месяц.');
